"""Cours tc_phys_mouvement_inertie — séances 4 et 5 : vecteur vitesse, MRU, MCU, centre d'inertie."""

CACHE = {'conclusions': False}


def apres(*moments, duree=7):
    et = [{'commande': 'set_parameters', 'parametres': {'conclusions': True}}]
    et += [{'commande': 'play_until', 'parametres': {'moment': m}} for m in moments]
    return [{'sim_avant': CACHE, 'etapes': et, 'duree_s': duree}]


